custom_css:
/*Content*/
input[type="text"]::placeholder,
input[type="email"]::placeholder,
textarea::placeholder{
    color: #c2c2c2 !important;
    font-size:14px !important;
}
.first-letter{
    font-size: 36px;
    font-family: "Fredoka One";
}
body p{
    letter-spacing: 0.03em;
}
.initial,
.capitalize{
    text-transform:initial !important;
}
.header-color-dark .menu-wrapper .menu > li.current-menu-item > a:after,
.header-color-dark .menu-wrapper .menu > li > a:hover:after{
    background-color: #fff;
    margin-top: 1px;
}
.title-hover:hover{
    color:#8ad6cc !important;
    cursor:pointer;
    transition:.2s;
}
.title-hover{
    transition:.3s;
}
.letter-4{
    letter-spacing:4px;
}
.letter-1{
    letter-spacing:1px;
}
/*top-bar*/
.top-bar .menu-element .menu .menu-item-has-children > a:after {
    color: #d7d7d7;
    transform: rotate(90deg);
}
#menu-currency .item-link,
#menu-language .item-link{
    color:#666;
    font-size:12px;
}
.menu-element .menu li > a {
    padding-right: 20px;
    padding-left: 10px;
}
.top-bar.topbar-color-dark > .container{
    max-width: 1300px;
}
.top-bar.topbar-color-dark .topbar-widget.etheme_widget_socials .et-follow-buttons a {
    border:none;
}
.top-bar.topbar-color-dark .topbar-widget.etheme_widget_socials .et-follow-buttons a i{
    color:#bfbfbf !important;
}
.top-bar.topbar-color-dark .topbar-widget.etheme_widget_socials .et-follow-buttons a:hover i{
    color:#8ad6cc !important;
}
.top-bar.topbar-color-dark .languages-area > div {
    border-right-color: #fff;
    
}
.top-bar.topbar-color-dark p{
    color: #b0b0b0;
    text-transform: uppercase;
    font-size: 11px;
}
.top-bar.topbar-color-dark {
    border-bottom: 1px solid #eeeeee;
    height: 40px;
}

/*Header*/
.fixed-header  .menu > li > a:hover:after {
    background-color: #8ad6cc !important;
}

.fixed-header{
    border:none !important;
}
.trigger{
    background:transparent !important;
}

.ajax-search-form.all-results-on .btn.filled,
.search-form-wrapper{
    border-radius:50px;
}
.header-bg-block #menu-main-menu-1 li:first-child:before{
    display:none;
}
.header-bg-block #menu-main-menu-1 li:first-child{
    padding-top:4px;
}
.header-bg-block #menu-main-menu-1  li:before{
    content:" ";
    width:4px;
    border-radius:60px;
    height:4px;
    background:#fff;
    display:block;
    top: 28px;
    left:-28px;
    position: relative;
}

.header-wrapper.header-advanced .header-search.act-default [role="searchform"] .btn:before{
  display:none;  
}
.header-wrapper.header-advanced .navigation-wrapper:before{
    background-color: rgba(0, 0, 0, 0);
}
.navigation-wrapper{
    height:60px;
    background-image:url(http://8theme.com/demo/xstore/2/baby-shop/wp-content/uploads/sites/8/2018/02/bg-menu.jpg);
}
/*Breadcrumbs*/
.back-history,
.breadcrumbs a,
.breadcrumbs + h1 > span,
.woocommerce-breadcrumb,
.woocommerce-breadcrumb a,
.page-heading .title{
    letter-spacing:0 !important;
}


/*Shop*/
.add_to_cart_button.ajax_add_to_cart:hover{
    background:#3c3c3c !important;
    border-color:#3c3c3c !important;
}
.woocommerce-pagination .page-numbers li a:hover{
    border-color:#8ad6cc !important;
}
.woocommerce-pagination .page-numbers li a{
    background:#fff !important;
    border-color:#fff !important;
    border-radius:60px !important;
    width:36px;
    color:#8e8e8e;
    font-size:13px;
}
.woocommerce-pagination .page-numbers li span{
    border-radius:60px !important;
    width:36px;
    font-size:13px;
}
.single-product .product-information-inner .price .woocommerce-Price-amount.amount {
    font-size: 20px;
}
.single-product .tagged_as a:hover{
    color:#8ad6cc !important;
}
.single-product .tagged_as a{
    color: #c2c2c2 !important;
    font-size: 15px;
    text-transform: lowercase !important;
    font-weight: 400 !important;
    font-family: "Open Sans";
}
.product-information .cart + .yith-wcwl-add-to-wishlist{
    margin-bottom: 15px;
}
.single-product .compare.button{
    margin-bottom:20px !important;
}
.single-product .qty-span,
.single-product .add_to_wishlist,
.single-product .compare.button,
.single-product .tagged_as{
    font-size: 16px !important;
    font-weight: 400;
    display: block;
    text-transform: capitalize;
    color: #3e3e3e;
    margin-bottom: 9px;
    font-family: Roboto;
    letter-spacing:0 !important;
}
.quantity.buttons_added input[type="number"] {
    width: 45px;
    color:#c2c2c2;
}
.quantity.buttons_added span {
    background-color: #fff;
    border: 1px solid #ebebeb;
    margin-right: -4px;
}
.quantity.buttons_added span.plus {
    margin-left: -5px !important;
}
.single-post .form-submit .submit{
    font-size:14px !important;
    height: 50px;
    width: 170px !important;
}
.single-product .add_to_cart_button.ajax_add_to_cart,
.single-post .form-submit .submit{
    background: #8ad6cc;
    border-color: #8ad6cc;
    border-radius: 60px !important;
    padding-top: 11px;
    padding-bottom:11px;
    min-width: 160px;
    font-size:13px;
    padding-left: 10px;
    padding-right: 10px;
}
.single-product .products-page-cats{
    display:none;
}
.single-product .product_title.entry-title{
    font-size: 28px;
    color: #3e3e3e;
    font-weight:400;
}
.content-page.container .products-title span {
    text-transform: uppercase;
    font-size: 30px;
    font-weight: 400;
    color: #3e3e3e;
}
.single-product .wc-tabs.tabs-nav a span:after{
    display:none;
}
.single-product .content-page.container .wpb_text_column.wpb_content_element{
    background:#fff;
} 
.single-product .wc-tabs.tabs-nav a:hover,
.single-product .wc-tabs li.active a{
    color:#8ad6cc !important;
}
.single-product .wc-tabs.tabs-nav a{
    color: #3e3e3e;
    font-family: "Fredoka One";
    font-size: 18px;
    padding: 5px 20px;
    font-weight: 400;
}
.shop_table.cart.wishlist_table .product-name .nobr{
    font-size:14px !important;
}
.single-product .swiper-entry.swipers-couple-wrapper  .swiper-slide,
.swiper-wrapper.right.thumbnails-list li.swiper-slide{
    border:1px solid #f4f4f4;
} 
.ajax-results-wrapper .product-title a,
.posts-ajax-list .post-title a{
     font-family: "Fredoka One";
    font-weight: 400;
    color:#545454 !important;
}

.after-shop-loop {
    margin-bottom: 50px;
}
.content-product .product-title a {
    margin-bottom: 0.3142em;
}
.product-title a{
    color: #545454;  
}
.archive .page-heading{
    margin-bottom:0 !important;
}
 .price .woocommerce-Price-amount.amount {
    color: #fab838;
    font-size: 15px;
    font-family: Roboto;
    font-weight:500;
}
.woocommerce-Reviews .comment-reply-title{
    color:#1e1e1e;
}

.content-product .products-page-cats a,
.content-product .products-page-brands a {
    font-size: 12px;
    color: #b7b7b7;
    font-weight: 400;
    text-transform: uppercase;
    letter-spacing: 0px;
}
.product-details .product-title a{
    font-size:15px;
    line-height: 24px;
}
.arhive .row.products-loop > div > div,
.single-product .content-product.product-inview,
.mpc-tab__content .content-product.product-inview{
    padding:10px;
    background:#fff;
}
.page-heading {
    margin-bottom: 10px;
}
.filter-wrap .products-per-page span {
    display: inline-block;
    color: #3e3e3e;
    font-weight: 400;
    text-transform: uppercase;
    font-size: 13px;
    font-family: "Fredoka One";
}
.view-switcher,
.filter-wrap .products-per-page{
    border-left-color:#f4f4f4;
}
.filter-wrap{
    border-color:#f4f4f4;
    margin-bottom: 50px;
}
.single-product .swiper-container.carousel-area{
    margin-bottom:80px;
}
.page-numbers li a:hover{
    background:#8ad6cc !important;
}
.articles-pagination a{
    background:#fff !important;
    border-color:#fff !important;
    font-size:13px;
    color:#8e8e8e;
}
.articles-pagination span,
.articles-pagination a{
    border-radius:10px !important;
    font-size:16px !important;
}
.breadcrumbs > div{
    letter-spacing:0 !important;
}
.articles-pagination a:hover{
    background:#8ad6cc !important;
    border-color:#8ad6cc !important;
}
.view-switcher .switch-list a:before,
.view-switcher .switch-grid a:before {
    color: #3e3e3e;
}
.view-switcher .switch-grid a,
.view-switcher .switch-list a{
    border-radius:70px;
    background:#e3fffb;
}
.shop-filters-area .widget-title span{
    color: #3e3e3e;
}
body .open-filters-btn .btn,
.price_slider_amount .button{
    background:#8ad6cc;
    border-radius:60px !important;
    border-color:#8ad6cc;
    color:#fff;
    font-family: "Fredoka One";
    font-size:13px;
    font-weight:400;
}

/*blog*/
.content-grid2:hover .meta-post-timeline .time-day,
.content-grid2:hover .meta-post-timeline .time-mon,
.slide-view-timeline2:hover .meta-post-timeline .time-day,
.slide-view-timeline2:hover .meta-post-timeline .time-mon{
    color: #fff !important;
}
.content-grid2 .meta-post-timeline,
.slide-view-timeline2 .meta-post-timeline{
    left: 60px;
    top: 42px;
    border: 4px solid #8ad6cc !important;
    border-radius: 23px;
}
.content-grid2 .meta-post-timeline .time-day,
.slide-view-timeline2 .meta-post-timeline .time-day{
    color: #3e3e3e !important;
    font-size: 24px;
    font-family: "Fredoka One";
    font-weight: 400;
    margin-top: 8px;
}
.content-grid2 .meta-post-timeline  .time-mon,
.slide-view-timeline2 .meta-post-timeline .time-mon{
    font-size: 14px;
    color: #3c3c3c;
    font-family: "Fredoka One";
    font-weight: 400;
    margin-top: -8px;
}
.blog .post-heading {
    margin-bottom: 1em;
}
.blog .post-comments-count span:last-child,
.home .post-comments-count span:last-child{
    display:none;
}
.blog .post-heading h2 a{
    color: #3e3e3e;
    font-size: 20px;
    letter-spacing: 1px;
}
.home .post-heading h2 a{
    color: #3e3e3e;
    font-size: 17px;
    letter-spacing: 1px;
}
.home .grid-post-body{
    padding:15px !important;
}
.home .posts-slider article .meta-post .post-comments-count {
    float: initial;
    margin-left: 15px;
}
.grid-post-body{
    text-align:center;
    padding-top:20px;
}
 .wp-picture.blog-hover-default,
 .grid-post-body,
 .home .posts-slider article > div .wp-picture{
    width: 50% !important;
    float: left;
}
.posts-slider article h2{
    margin-bottom:5px;
}
.post-categories{
    display:none;
}
.single-post .wp-picture.blog-hover-default{
    width: 100% !important;
}
.svg-wrapper .btn.btn-read-more{
    border-radius:40px;
}
.single-post .comment-respond{
    margin-bottom:3vw;
}
.comment-form input[type=text],
.comment-form input[type=email]{
    height:48px !important;
}

.comment-form textarea,
.comment-form input[type=text],
.comment-form input[type=email]{
    border-color:#8ad6cc !important;
}

.comments-list .comment {
    border-bottom: 1px solid #f4f4f4;
}
.comments-list .children {
    border-top: 1px solid #f4f4f4;
}
.single-post .comments .title-alt,
.comment-respond .comment-reply-title,
.articles-pagination{
    border-top: 1px solid #f4f4f4;
    border-bottom: 1px solid #f4f4f4;
}
.articles-pagination{
    margin-bottom: 5vw;
}
.single-post article{
    margin-top:-60px;
}
.title-alt span,
.comment-respond .comment-reply-title  span{
    color: #3e3e3e;
    font-size: 16px;
    font-weight: 400;
}
.single-post .share-post {
    padding: 20px 0 15px;
    border-top: 1px solid #f4f4f4;
    text-align: right;
}
.share-post .menu-social-icons li a:hover {
    display: inline-block;
    padding: 10px;
    border-radius: 10px;
    background: #8ad6cc;
    color: #fff !important;
    margin: 0 3px;
}
.author-info{
   border-top: 1px solid #f4f4f4; 
}
.media-body .media-heading{
    color: #3e3e3e;
    font-size: 20px;
}
.single-post .menu-social-icons li a {
    color: #999;
    padding: 10px;
    margin: 0 3px;
    width: 36px;
    height: 36px;
}
.share-post .share-title{
    color: #3e3e3e;
    font-size: 16px;
    font-weight: 400;
    padding-top:7px;
}
.meta-post .views-count:before{
    color:#8ad6cc;
}
.views-count,
.post-comments-count span{
    color:#c2c2c2 !important;
}
.post-heading .entry-title{
    color: #3e3e3e;
    text-transform: initial;
    text-align: center;
    margin-top: 50px;
    font-size:30px;
}
.post-heading .meta-post{
    text-align:center;
    font-size:15px;
}

/*Footer*/
footer.footer .mpc-divider{
    display:none;
}
footer.footer{
    background-size: cover;
    background-repeat: round;
}
footer.footer .widget-title{
    display:none;
}
.footer-link p,
.services-link p{
    margin-bottom:2px;
    cursor:pointer;
    color:#fff !important;
}



@media only screen and (max-width: 480px) {
    body .mpc-map-wrap.mpc-custom-height{
        height:300px !important;
    }
    body .banner-map .vc_column-inner{
        margin-top: 0 !important;
    }
    .wpcf7-form .form-group p:first-child {
        margin-bottom: 5px;
    }
    .responsive-bottom{
        margin-bottom:30px;
    }
    .responsive-size{
        font-size:40px !important;
    }
    .responsive-center *,
    .responsive-center{
        text-align:center !important;
    }
    body .banner-height{
        margin-left:0 !important;
    }
    body .wpb_revslider_element.wpb_content_element {
        margin-bottom: 5px !important;
    }
    body .banner__top > .vc_column-inner{
        padding-right:0 !important;
    }
    body  .banner__bottom > .vc_column-inner{
        padding-top:100px !important;
    }
    .categories-section .wpb_column  .vc_column-inner{
        margin-left:0 !important;
        margin-right:0 !important;
        margin-bottom:5px !important;
    }
    body .category-5 > .vc_column-inner,
    body .category-6 > .vc_column-inner{
        margin-top:0 !important;
    }
    .subscribe-row > .vc_column-inner{
        padding-left:25px !important;
        padding-right:25px !important;
    }
    .subscribe-row .wpb_text_column{
        margin-bottom: 10px !important;
    }
    body .left-banner .banner-content,
    body .right-banner .banner-content{
        left: 0 !important;
        right: 0px !important;
        width: auto;
        text-align: center !important;
        margin-top: 0px;
    }
     footer.footer *{
        text-align:center !important;
        
    }
    footer.footer{
        background-image: none !important;
    }
    .footer-link{
        width:50%;
        float:left;
    }
    footer.footer .mpc-icon-column__description.mpc-transition{
        margin-top: 0 !important;
    }

     body  article .posts-slider article > div .wp-picture,
     body .grid-post-body,
     body article.blog-post  .wp-picture.blog-hover-default{
        width: 100% !important;
        float: left;
    }   
    .home .mpc-tabs__nav-item .mpc-button__title{
        padding:10px !important;
    }
    .blog .grid-post-body{
        margin-bottom:80px
    }
    .blog article{
        clear:both !important;
    }
    .articles-pagination.align-right{
        text-align:center !important;
    }
    .single-post .wpb_single_image.wpb_content_element.vc_align_left{
        text-align:center !important;
    }
    .sb-infinite-scroll-load-more:not(.finished) a {
        border-radius: 40px;
        border: 1px solid #8ad6cc;
        color: #fff;
        height: 3.642rem;
        line-height: 3.5rem;
        background-color: #8ad6cc;
    }
    .after-shop-loop{
        border:none;
    }
    body .mpc-wc-category__wrap .mpc-category__thumbnail {
        position: absolute;
       right: 53px;
       top: -6px;
       width: 71%;
       height: 200px;
       background-size: contain !important;
       background-repeat: no-repeat;
       background-position: center;
    }
    .mpc-wc-category .mpc-category__wrapper {
        height: 230px !important;
    }
    .mpc-wc-category.mpc-transition{
        margin-bottom:40px;
    }
   body .category-first-block {
        margin-bottom:0px !important;
    }
    body .SB-section,
    body .section-categories{
        background-image: none !important;
    }
    .banner-kod{
        line-height: 85px;
        text-align:center;
    }
    .banner-content .content-inner p{
        display:none;
    }
    .banner-content h2:first-child{
        font-size:25px !important;
        margin-top:5px;
    }
     .banner-content h2:last-child{
        font-size:33px !important;
    }
}

@media only screen and (min-width: 993px){
   .header-wrapper.header-advanced header > .container .container-wrapper {
      padding-top: 30px;
      padding-bottom: 30px;
   }
}
